import{_ as s,l as i,o as e,c as n,v as t,p as d,x as o,d as l,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"x86-64 编码与寻址","description":"","frontmatter":{"title":"x86-64 编码与寻址","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/x86-64-encoding.md","filePath":"cs/x86-64-encoding.md","lastUpdated":1789023840000}'),E={name:"cs/x86-64-encoding.md"};function h(I,a,A,C,S,m){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="x86-64-编码与寻址" tabindex="-1">x86-64 编码与寻址 <a class="header-anchor" href="#x86-64-编码与寻址" aria-label="Permalink to &quot;x86-64 编码与寻址&quot;">​</a></h1><div class="epigraph"><p>指令长度从 1 字节到 15 字节不等：前缀、REX、ModR/M、SIB、位移与立即数拼出有效地址，译码是状态机，不是 RISC 的固定切片。</p><footer>—— 据 Intel 64 and IA-32 Architectures Software Developer’s Manual；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/bios-uefi">上一课</a>把控制交给加载器时，x86 上跑的是变长机器码。<a href="/cs/risc-cisc">RISC 与 CISC</a> 已对照原则。缺口是 <strong>x86-64 编码</strong>：REX 前缀把寄存器扩到 16 个，RIP-relative 寻址服务 <a href="/cs/pic">PIC</a>，ModR/M+SIB 表达复杂有效地址。本单元对照 ISA，不重写 Transformer，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 定长 32 位字段。<a href="/cs/riscv-int-isa">整数指令</a> 语义清晰。x86-64：遗留 8/16/32 位模式叠 64 位，前缀改宽度与段，ModR/M 的 mod/reg/r/m 决定是寄存器还是 <code>[base+index*scale+disp]</code>。缺口不是再讲 RISC 原则，而是这套<strong>变长码流</strong>如何切出下一条指令——边界识别本身就要顺序扫描。</p><p>寻址：多数运算可带一个内存操作数（CISC）；64 位下默认 RIP-relative 的 <code>disp32</code> 便于 PIC。栈用 <code>rsp</code>，调用约定后课 ABI 边界再与 SysV 对齐。</p><h3 id="变长不是「随便多长」" tabindex="-1">变长不是「随便多长」 <a class="header-anchor" href="#变长不是「随便多长」" aria-label="Permalink to &quot;变长不是「随便多长」&quot;">​</a></h3><p>最大 15 字节，超长不合法。把 x86 理解成比特流任意切，译码器会失同步（恶意指令流攻击是安全课）。长度解码要先吞前缀再看 opcode map。</p><p><span class="marginnote">Intel SDM 卷 2 是编码权威。AMD 兼容手册对照。Patterson/Hennessy 用 CISC 对照教学。本课不背全部 opcode 图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>取指：从 RIP 读字节，长度解码器输出下一条边界。有效地址：段基（64 位大多平坦）+ base + index×scale + disp。REX.W 选 64 位操作数，REX.R/X/B 扩展寄存器号。立即数跟在寻址字节后。</p>',11)),(e(),d(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BYTES%5B%22%E7%A0%81%E6%B5%81%22%5D%20--%3E%20LEN%5B%22%E9%95%BF%E5%BA%A6%E8%A7%A3%E7%A0%81%22%5D%0A%20%20LEN%20--%3E%20MODRM%5B%22ModR%2FM%20%2B%20SIB%22%5D%0A%20%20MODRM%20--%3E%20EA%5B%22%E6%9C%89%E6%95%88%E5%9C%B0%E5%9D%80%22%5D%0A%20%20EA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BE%AE%E7%A0%81%E6%8A%8A%E5%A4%8D%E6%9D%82%E6%8C%87%E4%BB%A4%E6%8B%86%E5%BC%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/cs/dma-scatter-gather">DMA</a> 无关：这是 CPU 取指。固件复位后先在 16 位实模式编码里，再进长模式——启动链已点过。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课微码：一条 CISC 变成多条 μop，内部更像 RISC。本课只让「指令从哪几个字节来、内存操作数地址怎么算」可讲。ARM/RISC-V 对照课会回来比密度与译码成本。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列 SSE 前缀全部，不把 VEX/EVEX 当本课主体（SIMD 课再接）。不写每条 legacy 指令的微码长度表。</p><p>后课默认：x86-64 是变长编码加 ModR/M 寻址；RIP-relative 是 64 位 PIC 的常用形。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>变长：前缀 + opcode + ModR/M/SIB + disp/imm。</li><li>一条指令可带内存操作数；RIP-relative 服务 PIC。</li><li>译码要顺序确定长度。</li><li>出处：Intel SDM；Patterson and Hennessy, COD；RISC-CISC 先修。</li></ul>',8))])}const R=s(E,[["render",h]]);export{x as __pageData,R as default};
